type Props = ComponentProps<typeof BenefitBlockDesktop>;
// image: выбери реальный ассет из Corp Image Library; размер, crop и segment сохранены в metadata
function Example({ image, primaryAction }: { image: Props['image']; primaryAction: { onClick: MouseEventHandler<HTMLButtonElement> } }) {
    return <BenefitBlockDesktop
        title={"Title 30-36"}
        image={image}
        imagePositionDesktop="right" compact={false}

        withBackground={true}
        preset="text" subtitle={"Subtitle"}
        primaryButtonProps={{ label: "Label", props: { ...primaryAction, disabled: false } }}

        backgroundPlateProps={{ children: null, view: BackgroundPlateView.Primary, level: 'outer', backgroundColor: 'base-bg-alt', showSkeleton: false,   }}
    />;
}

